create or replace function public.anaira_settle_hms_folio(p_restaurant_id uuid,p_folio_id uuid,p_amount numeric,p_method text,p_provider text default null,p_reference text default null) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; v_balance numeric; begin select balance into v_balance from hms_folios where id=p_folio_id and restaurant_id=p_restaurant_id for update; if not found then raise exception 'folio not found'; end if; if p_amount<=0 or p_amount>v_balance then raise exception 'invalid payment amount'; end if; insert into hms_folio_payments(restaurant_id,folio_id,amount,method,provider,reference) values(p_restaurant_id,p_folio_id,p_amount,p_method,p_provider,p_reference) returning id into v_id; update hms_folios set balance=greatest(0,balance-p_amount),status=case when balance-p_amount<=0 then 'paid' else status end,updated_at=now() where id=p_folio_id; return v_id; end $$;
create or replace function public.anaira_claim_workflow_jobs(p_tenant_id uuid,p_limit int default 20) returns setof public.crm_workflow_queue language sql security invoker set search_path=public,pg_temp as $$ with c as(select id from crm_workflow_queue where tenant_id=p_tenant_id and status='queued' and available_at<=now() order by available_at,id for update skip locked limit greatest(1,least(p_limit,100))) update crm_workflow_queue q set status='processing',claimed_at=now(),attempts=attempts+1 from c where q.id=c.id returning q.* $$;
create or replace function public.anaira_complete_workflow_job(p_job_id uuid,p_ok boolean,p_error text default null) returns void language sql security invoker set search_path=public,pg_temp as $$ update crm_workflow_queue set status=case when p_ok then 'completed' when attempts<5 then 'queued' else 'failed' end,last_error=case when p_ok then null else p_error end,completed_at=case when p_ok then now() else null end,available_at=case when p_ok then now() else now()+interval '5 minutes' end where id=p_job_id $$;
